{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2137-01-02 21:54:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I know you're not feeling well tonight. You're in the hospital now, and we're going to take care of you."
    },
    {
      "turn_number": 2,
      "time": "2137-01-02 21:55:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 3,
      "time": "2137-01-02 21:56:00",
      "speaker": "Doctor",
      "text": "I know you can't speak, but we’re aware of your history — quadriplegia, tracheostomy, diabetes, and recent infections. You came in because you weren’t responding like usual and had low oxygen."
    },
    {
      "turn_number": 4,
      "time": "2137-01-02 21:57:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 5,
      "time": "2137-01-02 21:58:00",
      "speaker": "Doctor",
      "text": "We checked your blood and found very high sodium and sugar. Your kidneys aren’t working as well right now. We’re giving you fluids and insulin to help."
    },
    {
      "turn_number": 6,
      "time": "2137-01-02 22:00:00",
      "speaker": "Doctor",
      "text": "Your blood pressure dropped earlier, so we started medicine to support it. You’re on antibiotics too, in case an infection is making you sick."
    },
    {
      "turn_number": 7,
      "time": "2137-01-02 22:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 8,
      "time": "2137-01-02 22:04:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray. It shows some lung changes, but it’s hard to tell if it’s infection or just fluid buildup. You’re breathing on your own with the trach mask, which is good."
    },
    {
      "turn_number": 9,
      "time": "2137-01-02 22:06:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 10,
      "time": "2137-01-02 22:08:00",
      "speaker": "Doctor",
      "text": "We’ve reached your family. They know you’re a DNR/DNI and were considering comfort care. They want to talk more with us tomorrow."
    },
    {
      "turn_number": 11,
      "time": "2137-01-03 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are improving — sodium is coming down, and your sugars are more stable. But your white blood count is still high, which suggests infection."
    },
    {
      "turn_number": 12,
      "time": "2137-01-03 08:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 13,
      "time": "2137-01-03 08:04:00",
      "speaker": "Doctor",
      "text": "We’re continuing the same antibiotics. Your kidney function hasn’t improved yet, but we’re watching closely."
    },
    {
      "turn_number": 14,
      "time": "2137-01-03 08:06:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 15,
      "time": "2137-01-03 08:08:00",
      "speaker": "Doctor",
      "text": "Your family will be here soon. We’ll talk about your goals — whether to keep pushing with treatment or focus on comfort."
    },
    {
      "turn_number": 16,
      "time": "2137-01-03 14:00:00",
      "speaker": "Doctor",
      "text": "We just spoke with your family. After hearing everything, they’ve decided to shift to comfort measures only. That means we’ll stop aggressive treatments and focus on keeping you peaceful."
    },
    {
      "turn_number": 17,
      "time": "2137-01-03 14:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 18,
      "time": "2137-01-03 14:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep you comfortable with medications like methadone for any discomfort and Ativan if you seem anxious. You’ll stay in this room, and your family can visit anytime."
    },
    {
      "turn_number": 19,
      "time": "2137-01-03 14:06:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 20,
      "time": "2137-01-03 14:08:00",
      "speaker": "Doctor",
      "text": "The palliative care team will help us manage your symptoms. You’re not alone in this."
    },
    {
      "turn_number": 21,
      "time": "2137-01-04 09:00:00",
      "speaker": "Doctor",
      "text": "Hi, it’s morning rounds. You’re still stable, but not responsive. Your breathing is slow but regular. We’re continuing comfort meds."
    },
    {
      "turn_number": 22,
      "time": "2137-01-04 09:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 23,
      "time": "2137-01-04 09:04:00",
      "speaker": "Doctor",
      "text": "Your family was here last night. They held your hand and said they love you. They’re grateful for the care you’re getting."
    },
    {
      "turn_number": 24,
      "time": "2137-01-05 08:30:00",
      "speaker": "Doctor",
      "text": "You’re still with us, and we’re keeping you comfortable. Your breathing is a bit more shallow today, but you’re not in distress."
    },
    {
      "turn_number": 25,
      "time": "2137-01-05 08:32:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 26,
      "time": "2137-01-05 08:34:00",
      "speaker": "Doctor",
      "text": "We’ve turned off the alarms on the monitors so it’s quiet. The room is dimmed. Your family knows changes may happen anytime."
    },
    {
      "turn_number": 27,
      "time": "2137-01-06 10:15:00",
      "speaker": "Doctor",
      "text": "Your breathing is slower now. We’ve increased the methadone slightly to make sure you’re not struggling. You’re still peaceful."
    },
    {
      "turn_number": 28,
      "time": "2137-01-06 10:17:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 29,
      "time": "2137-01-07 11:00:00",
      "speaker": "Doctor",
      "text": "Family is here. We’re all here with you. You’re not alone."
    },
    {
      "turn_number": 30,
      "time": "2137-01-07 11:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 31,
      "time": "2137-01-08 07:45:00",
      "speaker": "Doctor",
      "text": "Your breathing is very slow. We’ve placed extra pillows to make you comfortable. The chaplain stopped by to offer a blessing."
    },
    {
      "turn_number": 32,
      "time": "2137-01-08 07:47:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 33,
      "time": "2137-01-09 13:20:00",
      "speaker": "Doctor",
      "text": "You’re still breathing, very quietly. Your family has been taking turns sitting with you. They said thank you for everything you’ve given them."
    },
    {
      "turn_number": 34,
      "time": "2137-01-09 13:22:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 35,
      "time": "2137-01-10 06:30:00",
      "speaker": "Doctor",
      "text": "You’re still with us. We’ve kept the room warm and quiet. Your son stayed all night."
    },
    {
      "turn_number": 36,
      "time": "2137-01-10 06:32:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 37,
      "time": "2137-01-11 15:00:00",
      "speaker": "Doctor",
      "text": "Your breathing is irregular now. We’re here, and your family is on their way. You’re not in pain. You’re safe."
    },
    {
      "turn_number": 38,
      "time": "2137-01-11 15:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 39,
      "time": "2137-01-12 18:45:00",
      "speaker": "Doctor",
      "text": "Family is gathered. We’re all here with you. You’ve been so strong."
    },
    {
      "turn_number": 40,
      "time": "2137-01-12 18:47:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 41,
      "time": "2137-01-13 03:15:00",
      "speaker": "Doctor",
      "text": "You’re still breathing, very softly. We’ve turned off all non-essential equipment. Your daughter is holding your hand."
    },
    {
      "turn_number": 42,
      "time": "2137-01-13 03:17:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 43,
      "time": "2137-01-13 10:00:00",
      "speaker": "Doctor",
      "text": "You’re still here. We’re keeping you comfortable. Your family is taking turns speaking to you."
    },
    {
      "turn_number": 44,
      "time": "2137-01-13 10:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 45,
      "time": "2137-01-13 21:30:00",
      "speaker": "Doctor",
      "text": "You’re very close now. We’re all here. You’re not alone."
    },
    {
      "turn_number": 46,
      "time": "2137-01-13 21:32:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 47,
      "time": "2137-01-13 23:00:00",
      "speaker": "Doctor",
      "text": "You’ve passed peacefully. Your family is here. Thank you for letting us care for you."
    },
    {
      "turn_number": 48,
      "time": "2137-01-13 23:02:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 49,
      "time": "2137-01-13 23:04:00",
      "speaker": "Doctor",
      "text": "We’ll call the time of death as 23:00. Your family wants to spend a little more time with you. That’s completely okay."
    },
    {
      "turn_number": 50,
      "time": "2137-01-13 23:06:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 51,
      "time": "2137-01-13 23:08:00",
      "speaker": "Doctor",
      "text": "We’ll notify the funeral home when the family is ready. They’ve declined an autopsy."
    },
    {
      "turn_number": 52,
      "time": "2137-01-13 23:10:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 53,
      "time": "2137-01-13 23:12:00",
      "speaker": "Doctor",
      "text": "You’ve been through so much. You’re at rest now."
    },
    {
      "turn_number": 54,
      "time": "2137-01-13 23:14:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 55,
      "time": "2137-01-13 23:16:00",
      "speaker": "Doctor",
      "text": "We’ll make sure your records reflect the dignity and care you received."
    },
    {
      "turn_number": 56,
      "time": "2137-01-13 23:18:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 57,
      "time": "2137-01-13 23:20:00",
      "speaker": "Doctor",
      "text": "Your family asked us to thank the team. They’re so grateful for how gently you were treated."
    },
    {
      "turn_number": 58,
      "time": "2137-01-13 23:22:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 59,
      "time": "2137-01-13 23:24:00",
      "speaker": "Doctor",
      "text": "We’ll stay with you until they’re ready to say goodbye."
    },
    {
      "turn_number": 60,
      "time": "2137-01-13 23:26:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 61,
      "time": "2137-01-13 23:28:00",
      "speaker": "Doctor",
      "text": "You’re not in pain. You’re not struggling. You’re at peace."
    },
    {
      "turn_number": 62,
      "time": "2137-01-13 23:30:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 63,
      "time": "2137-01-13 23:32:00",
      "speaker": "Doctor",
      "text": "We’ll continue to honor your journey with respect and care."
    },
    {
      "turn_number": 64,
      "time": "2137-01-13 23:34:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 65,
      "time": "2137-01-13 23:36:00",
      "speaker": "Doctor",
      "text": "Your family is still here. They’re saying their final words."
    },
    {
      "turn_number": 66,
      "time": "2137-01-13 23:38:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 67,
      "time": "2137-01-13 23:40:00",
      "speaker": "Doctor",
      "text": "We’ll give them all the time they need."
    },
    {
      "turn_number": 68,
      "time": "2137-01-13 23:42:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 69,
      "time": "2137-01-13 23:44:00",
      "speaker": "Doctor",
      "text": "You’ve been surrounded by love until the very end."
    },
    {
      "turn_number": 70,
      "time": "2137-01-13 23:46:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 71,
      "time": "2137-01-13 23:48:00",
      "speaker": "Doctor",
      "text": "We’ll make sure everything is handled with care."
    },
    {
      "turn_number": 72,
      "time": "2137-01-13 23:50:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 73,
      "time": "2137-01-13 23:52:00",
      "speaker": "Doctor",
      "text": "Thank you for letting us be part of your story."
    },
    {
      "turn_number": 74,
      "time": "2137-01-13 23:54:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 75,
      "time": "2137-01-13 23:56:00",
      "speaker": "Doctor",
      "text": "You’re at rest now. No more pain. No more struggle."
    },
    {
      "turn_number": 76,
      "time": "2137-01-13 23:58:00",
      "speaker": "Patient",
      "text": "..."
    },
    {
      "turn_number": 77,
      "time": "2137-01-14 00:00:00",
      "speaker": "Doctor",
      "text": "Time of death is officially recorded as 2137-01-14 00:00:00. We’ll stay with you until your family is ready to say goodbye."
    }
  ],
  "summary": {
    "admission_start": "2137-01-02 21:54:00",
    "admission_end": "2137-01-14 00:00:00",
    "summary_paragraph": "A 68-year-old male with a complex medical history including quadriplegia, tracheostomy, GJ tube, atrial fibrillation, and type 2 diabetes was admitted from rehab for altered mental status and hypoxia. He presented with septic shock, severe hypernatremia, acute kidney injury, and diabetic ketoacidosis. Despite initial aggressive support with pressors, IV fluids, insulin, and broad-spectrum antibiotics, his condition remained critical. After extensive discussions with family, goals of care were transitioned to comfort measures only. He was managed with palliative medications and passed peacefully on hospital day 12. The family declined post-mortem evaluation.",
    "problems": [
      "Unspecified septicemia",
      "Septic shock",
      "Other shock without mention of trauma",
      "Quadriplegia, unspecified",
      "Pressure ulcer, stage IV",
      "Acute kidney failure, unspecified",
      "Diabetes with ketoacidosis, type II or unspecified type, uncontrolled",
      "Hyperosmolality and/or hypernatremia",
      "Pressure ulcer, buttock",
      "Chronic respiratory failure",
      "Severe sepsis",
      "Long-term (current) use of insulin",
      "Polyneuropathy in diabetes",
      "Encounter for palliative care",
      "Late effects of cerebrovascular disease, other paralytic syndrome, bilateral",
      "Late effects of cerebrovascular disease, speech and language deficit, unspecified",
      "Unspecified acquired hypothyroidism",
      "Depressive disorder, not elsewhere classified",
      "Tracheostomy status",
      "Gastrostomy status",
      "Atrial fibrillation",
      "Long-term (current) use of anticoagulants",
      "Diabetes with neurological manifestations, type II or unspecified type, uncontrolled"
    ]
  }
}
